# ──────────────────────────────────────────
# 학생 명단
# ──────────────────────────────────────────
STUDENTS = [
    "강서윤","강주은","김나연","김윤서","김효린",
    "박소영","박이현","박채은","유주원","조성아",
    "최아령","홍윤지","강민재","김남우","김민재",
    "김민중","김우석","송민호","신승민","이정현",
    "정준이","조예성","최승운","최태민","한준서",
]

# ──────────────────────────────────────────
# 자리 구조
# col1:5행, col2:5행 → 1분단 (10자리)
# col3:4행, col4:4행 → 2분단 (8자리)
# col5:4행, col6:3행 → 3분단 (7자리)  총 25자리
# ──────────────────────────────────────────
SEAT_STRUCTURE = {1: 5, 2: 5, 3: 4, 4: 4, 5: 4, 6: 3}

# 분단 그룹: (왼쪽열, 오른쪽열)
GROUPS = [(1, 2), (3, 4), (5, 6)]
GROUP_NAMES = ["1분단", "2분단", "3분단"]

def generate_all_seats():
    seats = []
    for col, max_row in SEAT_STRUCTURE.items():
        for row in range(1, max_row + 1):
            seats.append((col, row))
    return seats

ALL_SEATS = generate_all_seats()

# ──────────────────────────────────────────
# 세션 상태
# ──────────────────────────────────────────
if "seating" not in st.session_state:
    st.session_state.seating = None
if "status_text" not in st.session_state:
    st.session_state.status_text = ""
if "status_color" not in st.session_state:
    st.session_state.status_color = "#27ae60"
if "fixed_seats" not in st.session_state:
    st.session_state.fixed_seats = {}

# ──────────────────────────────────────────
# 자리배치 생성
# ──────────────────────────────────────────
def create_seating(fixed={}):
    result = {}
    fixed_names = set(fixed.values())
    for seat, name in fixed.items():
        result[seat] = name
    remaining = [s for s in STUDENTS if s not in fixed_names]
    remaining_seats = [s for s in ALL_SEATS if s not in fixed]
    random.shuffle(remaining)
    for seat, name in zip(remaining_seats, remaining):
        result[seat] = name
    return result

# ──────────────────────────────────────────
# 분단별 HTML 렌더링
# ──────────────────────────────────────────
def render_seating(seating, cover_all=False):
    html = '<div class="seating-wrap">'

    for (lcol, rcol), gname in zip(GROUPS, GROUP_NAMES):
        max_r = max(SEAT_STRUCTURE[lcol], SEAT_STRUCTURE[rcol])
        html += f'<div class="group-box">'
        html += f'<div class="group-label">📎 {gname}</div>'

        for row in range(1, max_r + 1):
            html += '<div class="seat-row">'
            for col in [lcol, rcol]:
                seat = (col, row)
                has_seat = row <= SEAT_STRUCTURE[col]
                if not has_seat:
                    html += '<div class="seat seat-empty"></div>'
                    continue
                name = seating.get(seat, "")
                is_fixed = seat in st.session_state.fixed_seats
                if cover_all:
                    html += '<div class="seat seat-cover">🎲</div>'
                elif is_fixed:
                    html += f'<div class="seat seat-fixed">📌<br>{name}</div>'
                else:
                    html += f'<div class="seat seat-normal">{name}</div>'
            html += '</div>'  # seat-row

        html += '</div>'  # group-box

    html += '</div>'  # seating-wrap
    return html

# ──────────────────────────────────────────
# 고정자리 파싱
# ──────────────────────────────────────────
def parse_fixed(raw):
    fixed = {}
    for line in raw.strip().split("\n"):
        line = line.strip()
        if not line:
            continue
        parts = line.split(",")
        if len(parts) == 3:
            try:
                col, row, name = int(parts[0]), int(parts[1]), parts[2].strip()
                fixed[(col, row)] = name
            except:
                pass
    return fixed

# ──────────────────────────────────────────
# UI
# ──────────────────────────────────────────
st.markdown('<div class="overlay">', unsafe_allow_html=True)
st.markdown('<div class="title">📚 3학년 3반 자리배치 📚</div>', unsafe_allow_html=True)

col1, col2 = st.columns(2)
with col1:
    rounds = st.number_input("뽑기 횟수", min_value=1, max_value=20, value=5, step=1)
with col2:
    fixed_raw = st.text_area(
        "고정자리 (열,행,이름)",
        placeholder="예시:\n1,1,강서윤\n6,3,한준서",
        height=80
    )

btn_col1, btn_col2 = st.columns(2)
with btn_col1:
    start = st.button("🎲 자리배치 시작!", use_container_width=True, type="primary")
with btn_col2:
    reset_btn = st.button("🔄 초기화", use_container_width=True)

if reset_btn:
    st.session_state.seating = None
    st.session_state.status_text = ""
    st.rerun()

if start:
    st.session_state.fixed_seats = parse_fixed(fixed_raw)
    placeholder = st.empty()

    # 1 ~ (rounds-1): 빠르게 섞기
    for i in range(rounds - 1):
        seating = create_seating(st.session_state.fixed_seats)
        with placeholder.container():
            st.markdown(f'<div class="status" style="color:#e67e22;">🔄 섞는 중... ({i+1}/{rounds})</div>', unsafe_allow_html=True)
            st.markdown('<div class="board">🖊 칠 판 🖊</div>', unsafe_allow_html=True)
            st.markdown(render_seating(seating, cover_all=False), unsafe_allow_html=True)
        time.sleep(0.3)

    # 마지막 뽑기: 3초 가림막
    final_seating = create_seating(st.session_state.fixed_seats)
    with placeholder.container():
        st.markdown(f'<div class="status" style="color:#e74c3c;">🎲 최종 뽑기! ({rounds}/{rounds}) 두구두구두구...</div>', unsafe_allow_html=True)
        st.markdown('<div class="board">🖊 칠 판 🖊</div>', unsafe_allow_html=True)
        st.markdown(render_seating(final_seating, cover_all=True), unsafe_allow_html=True)
    time.sleep(3)

    # 최종 공개
    st.session_state.seating = final_seating
    st.session_state.status_text = "🎉 자리배치 완료!"
    st.session_state.status_color = "#27ae60"
    st.rerun()

# 결과 표시
if st.session_state.seating:
    st.markdown(
        f'<div class="status" style="color:{st.session_state.status_color};">{st.session_state.status_text}</div>',
        unsafe_allow_html=True
    )
    st.markdown('<div class="board">🖊 칠 판 🖊</div>', unsafe_allow_html=True)
    st.markdown(render_seating(st.session_state.seating, cover_all=False), unsafe_allow_html=True)
    st.markdown('<div style="text-align:center;margin-top:12px;font-size:11px;color:#555;">📌 파란색: 고정자리</div>', unsafe_allow_html=True)

st.markdown('</div>', unsafe_allow_html=True)
